// expectDelim reads the next token and asserts it is the given delimiter.
func expectDelim(dec *json.Decoder, want json.Delim) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	d, ok := tok.(json.Delim)
	if !ok || d != want {
		return fmt.Errorf("abi: expected %q, got %v", want, tok)
	}
	return nil
}

// readKey reads the next token and asserts it is a string object key.
func readKey(dec *json.Decoder) (string, error) {
	tok, err := dec.Token()
	if err != nil {
		return "", err
	}
	key, ok := tok.(string)
	if !ok {
		return "", fmt.Errorf("abi: expected string key, got %v", tok)
	}
	return key, nil
}

// readRaw captures the next complete JSON value's exact source bytes by
// slicing the original input between the decoder's offsets before and after
// a depth-tracking token scan of the value. The returned bytes are verbatim
// (no re-serialization), so an opaque passthrough field re-marshals
// byte-identically and a nested def value can be handed to its own
// UnmarshalJSON. It uses only Decoder.More, Decoder.Token, and
// Decoder.InputOffset — no Decoder.Decode dispatch.
func readRaw(dec *json.Decoder, data []byte) (json.RawMessage, error) {
	// InputOffset before the first value token points just past the
	// preceding token (an object key, a preceding array element, or
	// nothing), so the slice may carry a leading key/value separator (:),
	// an array-element separator (,), and whitespace; the value's own bytes
	// are recovered by trimming those leading non-value bytes. The trailing
	// offset is exact (just past the value's last token).
	start := dec.InputOffset()
	depth := 0
	for {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		if d, ok := tok.(json.Delim); ok {
			if d == '{' || d == '[' {
				depth++
			} else {
				depth--
			}
		}
		if depth == 0 {
			break
		}
	}
	end := dec.InputOffset()
	value := bytes.TrimLeft(data[start:end], " \t\n\r:,")
	out := make(json.RawMessage, len(value))
	copy(out, value)
	return out, nil
}

// refuseUndeclaredJSONKeys walks the top-level keys of a JSON object and
// reports the first one the declared key set does not contain. It reads only
// the object's own keys — it never descends into a value — so it is the shape
// check for a payload whose identity is carried by which keys it holds.
func refuseUndeclaredJSONKeys(data []byte, declared ...string) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := expectDelim(dec, '{'); err != nil {
		return err
	}
	for dec.More() {
		key, err := readKey(dec)
		if err != nil {
			return err
		}
		found := false
		for _, d := range declared {
			if key == d {
				found = true
				break
			}
		}
		if !found {
			return fmt.Errorf("abi: unexpected field %q", key)
		}
		if _, err := readRaw(dec, data); err != nil {
			return err
		}
	}
	return expectDelim(dec, '}')
}

// readString decodes the next token as a JSON string.
func readString(dec *json.Decoder) (string, error) {
	tok, err := dec.Token()
	if err != nil {
		return "", err
	}
	s, ok := tok.(string)
	if !ok {
		return "", fmt.Errorf("abi: expected string, got %v", tok)
	}
	return s, nil
}

// readFloat decodes the next token as a JSON number.
func readFloat(dec *json.Decoder) (float64, error) {
	tok, err := dec.Token()
	if err != nil {
		return 0, err
	}
	f, ok := tok.(float64)
	if !ok {
		return 0, fmt.Errorf("abi: expected number, got %v", tok)
	}
	return f, nil
}

// readInt decodes the next token as a JSON number and truncates to int.
func readInt(dec *json.Decoder) (int, error) {
	f, err := readFloat(dec)
	if err != nil {
		return 0, err
	}
	return int(f), nil
}

// readBool decodes the next token as a JSON bool.
func readBool(dec *json.Decoder) (bool, error) {
	tok, err := dec.Token()
	if err != nil {
		return false, err
	}
	v, ok := tok.(bool)
	if !ok {
		return false, fmt.Errorf("abi: expected bool, got %v", tok)
	}
	return v, nil
}

// readBytes decodes the next token as a base64 JSON string into bytes,
// matching encoding/json's []byte wire form.
func readBytes(dec *json.Decoder) ([]byte, error) {
	s, err := readString(dec)
	if err != nil {
		return nil, err
	}
	return base64.StdEncoding.DecodeString(s)
}

// hexDigits is the lowercase hex alphabet for \u escapes.
const hexDigits = "0123456789abcdef"

// writeJSONString writes s as a JSON string literal, matching
// encoding/json's default (HTML-safe) string escaping byte-for-byte:
// it escapes the quote, backslash, control characters, the HTML-sensitive
// bytes <, >, and &, and the line/paragraph separators U+2028/U+2029.
func writeJSONString(buf *bytes.Buffer, s string) {
	buf.WriteByte('"')
	start := 0
	for i := 0; i < len(s); {
		if c := s[i]; c < utf8.RuneSelf {
			if c >= ' ' && c != '"' && c != '\\' && c != '<' && c != '>' && c != '&' {
				i++
				continue
			}
			if start < i {
				buf.WriteString(s[start:i])
			}
			switch c {
			case '"':
				buf.WriteString(`\"`)
			case '\\':
				buf.WriteString(`\\`)
			case '\n':
				buf.WriteString(`\n`)
			case '\r':
				buf.WriteString(`\r`)
			case '\t':
				buf.WriteString(`\t`)
			default:
				buf.WriteString(`\u00`)
				buf.WriteByte(hexDigits[c>>4])
				buf.WriteByte(hexDigits[c&0xF])
			}
			i++
			start = i
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == '\u2028' || r == '\u2029' {
			if start < i {
				buf.WriteString(s[start:i])
			}
			buf.WriteString(`\u202`)
			buf.WriteByte(hexDigits[r&0xF])
			i += size
			start = i
			continue
		}
		i += size
	}
	if start < len(s) {
		buf.WriteString(s[start:])
	}
	buf.WriteByte('"')
}

// writeJSONFloat writes f as a JSON number, matching encoding/json's
// float formatting (the shortest round-trippable form, with the small
// exponent-notation cutover encoding/json uses).
func writeJSONFloat(buf *bytes.Buffer, f float64) error {
	if f != f || f-f != 0 {
		return fmt.Errorf("abi: unsupported float value %v", f)
	}
	abs := f
	if abs < 0 {
		abs = -abs
	}
	fmt := byte('f')
	if abs != 0 && (abs < 1e-6 || abs >= 1e21) {
		fmt = 'e'
	}
	out := strconv.AppendFloat(nil, f, fmt, -1, 64)
	if fmt == 'e' {
		n := len(out)
		if n >= 4 && out[n-4] == 'e' && out[n-3] == '-' && out[n-2] == '0' {
			out[n-2] = out[n-1]
			out = out[:n-1]
		}
	}
	buf.Write(out)
	return nil
}

// writeJSONBytes writes b as a base64 JSON string, matching
// encoding/json's []byte wire form.
func writeJSONBytes(buf *bytes.Buffer, b []byte) {
	buf.WriteByte('"')
	buf.WriteString(base64.StdEncoding.EncodeToString(b))
	buf.WriteByte('"')
}

// appendCBORHead appends a CBOR head: the major type in the top three bits and
// the shortest length/argument encoding.
func appendCBORHead(dst []byte, major byte, arg uint64) []byte {
	mb := major << 5
	switch {
	case arg < 24:
		return append(dst, mb|byte(arg))
	case arg < 0x100:
		return append(dst, mb|24, byte(arg))
	case arg < 0x10000:
		return append(dst, mb|25, byte(arg>>8), byte(arg))
	case arg < 0x100000000:
		return append(dst, mb|26, byte(arg>>24), byte(arg>>16), byte(arg>>8), byte(arg))
	default:
		return append(dst, mb|27,
			byte(arg>>56), byte(arg>>48), byte(arg>>40), byte(arg>>32),
			byte(arg>>24), byte(arg>>16), byte(arg>>8), byte(arg))
	}
}

// appendCBORInt appends a signed integer as CBOR major type 0 (non-negative) or
// 1 (negative), shortest head.
func appendCBORInt(dst []byte, i int64) []byte {
	if i < 0 {
		return appendCBORHead(dst, 1, uint64(-1-i))
	}
	return appendCBORHead(dst, 0, uint64(i))
}

// appendCBORTextString appends s as a CBOR text string (major 3): shortest
// length head then the UTF-8 bytes verbatim.
func appendCBORTextString(dst []byte, s string) []byte {
	dst = appendCBORHead(dst, 3, uint64(len(s)))
	return append(dst, s...)
}

// appendCBORByteString appends b as a CBOR byte string (major 2): shortest
// length head then the bytes verbatim.
func appendCBORByteString(dst, b []byte) []byte {
	dst = appendCBORHead(dst, 2, uint64(len(b)))
	return append(dst, b...)
}

// appendCBORBool appends the fixed single-byte CBOR bool.
func appendCBORBool(dst []byte, v bool) []byte {
	if v {
		return append(dst, 0xf5)
	}
	return append(dst, 0xf4)
}

// appendCBORFloat appends f as a canonical CBOR float per CBOR CDE §4.2: the
// shortest of float16/float32/float64 that round-trips to the exact value, with
// NaN canonicalized to 0xf97e00, ±Inf to the float16 infinities, and ±0
// preserved by sign. No numeric reduction: an integer-valued float stays a
// float.
func appendCBORFloat(dst []byte, f float64) []byte {
	switch {
	case math.IsNaN(f):
		return append(dst, 0xf9, 0x7e, 0x00)
	case math.IsInf(f, 1):
		return append(dst, 0xf9, 0x7c, 0x00)
	case math.IsInf(f, -1):
		return append(dst, 0xf9, 0xfc, 0x00)
	}
	f32 := float32(f)
	if float64(f32) == f {
		if h, ok := f32ToF16Exact(math.Float32bits(f32)); ok {
			return append(dst, 0xf9, byte(h>>8), byte(h))
		}
		bits := math.Float32bits(f32)
		return append(dst, 0xfa, byte(bits>>24), byte(bits>>16), byte(bits>>8), byte(bits))
	}
	bits := math.Float64bits(f)
	return append(dst, 0xfb,
		byte(bits>>56), byte(bits>>48), byte(bits>>40), byte(bits>>32),
		byte(bits>>24), byte(bits>>16), byte(bits>>8), byte(bits))
}

// f32ToF16Exact converts float32 bits to a float16 if the value is EXACTLY
// representable (no rounding), returning the 16-bit encoding and true. It is
// used only to select the shortest float that round-trips, so a lossy
// conversion returns false and the caller keeps the wider width. ±0 preserves
// its sign; Inf/NaN are handled by the caller.
func f32ToF16Exact(b uint32) (uint16, bool) {
	sign := uint16((b >> 16) & 0x8000)
	exp := int32((b >> 23) & 0xff)
	mant := b & 0x7fffff
	if exp == 0 {
		if mant == 0 {
			return sign, true // ±0
		}
		return 0, false // float32 subnormal: not float16-exact
	}
	if exp == 0xff {
		return 0, false // Inf/NaN: handled by the caller
	}
	e := exp - 127
	switch {
	case e >= -14 && e <= 15:
		if mant&0x1fff != 0 {
			return 0, false // low mantissa bits would be lost
		}
		return sign | uint16((e+15)<<10) | uint16(mant>>13), true
	case e >= -24 && e <= -15:
		full := mant | 0x800000 // add the implicit leading 1
		shift := uint32(-(e + 1))
		if full&((1<<shift)-1) != 0 {
			return 0, false // low bits would be lost
		}
		hm := full >> shift
		if hm == 0 || hm > 0x3ff {
			return 0, false
		}
		return sign | uint16(hm), true
	default:
		return 0, false
	}
}

// float16ToFloat64 expands a CBOR half-precision float to float64.
func float16ToFloat64(h uint16) float64 {
	sign := uint32(h&0x8000) << 16
	exp := uint32(h>>10) & 0x1f
	mant := uint32(h & 0x3ff)
	switch exp {
	case 0:
		if mant == 0 {
			return float64(math.Float32frombits(sign)) // ±0
		}
		e := uint32(0)
		for mant&0x400 == 0 {
			mant <<= 1
			e++
		}
		mant &= 0x3ff
		exp32 := uint32(127 - 15 - e + 1)
		return float64(math.Float32frombits(sign | (exp32 << 23) | (mant << 13)))
	case 0x1f:
		if mant == 0 {
			return float64(math.Float32frombits(sign | 0x7f800000)) // ±Inf
		}
		return float64(math.Float32frombits(sign | 0x7f800000 | (mant << 13))) // NaN
	default:
		exp32 := exp - 15 + 127
		return float64(math.Float32frombits(sign | (exp32 << 23) | (mant << 13)))
	}
}

// sortCBORKeys sorts map keys into canonical CBOR order: by the bytewise order
// of their encoded text-key bytes (length head first, then UTF-8 content).
func sortCBORKeys(keys []string) {
	sort.Slice(keys, func(i, j int) bool { return cborLessKey(keys[i], keys[j]) })
}

// cborLessKey is the runtime twin of the generator's key comparator.
func cborLessKey(a, b string) bool {
	if len(a) != len(b) {
		ha := cborStrHeadBytes(len(a))
		hb := cborStrHeadBytes(len(b))
		return bytes.Compare(ha, hb) < 0
	}
	return a < b
}

// cborStrHeadBytes returns the CBOR text-string length head for a string of the
// given byte length.
func cborStrHeadBytes(n int) []byte {
	switch {
	case n < 24:
		return []byte{0x60 | byte(n)}
	case n < 0x100:
		return []byte{0x78, byte(n)}
	case n < 0x10000:
		return []byte{0x79, byte(n >> 8), byte(n)}
	default:
		return []byte{0x7a, byte(n >> 24), byte(n >> 16), byte(n >> 8), byte(n)}
	}
}

// cborDec is a minimal canonical-CBOR reader over a byte slice. It reads only
// the definite-length items the codec produces; indefinite lengths and
// unsupported majors are rejected loudly.
type cborDec struct {
	data []byte
	pos  int
}

// readHead reads one item head, returning the major type, the additional-info
// nibble, and the decoded argument (the immediate for ai < 24, else the
// big-endian follow bytes).
func (d *cborDec) readHead() (byte, byte, uint64, error) {
	if d.pos >= len(d.data) {
		return 0, 0, 0, fmt.Errorf("abi: cbor: unexpected end of input")
	}
	ib := d.data[d.pos]
	d.pos++
	major := ib >> 5
	ai := ib & 0x1f
	switch {
	case ai < 24:
		return major, ai, uint64(ai), nil
	case ai == 24:
		if d.pos+1 > len(d.data) {
			return 0, 0, 0, fmt.Errorf("abi: cbor: truncated 1-byte argument")
		}
		v := uint64(d.data[d.pos])
		d.pos++
		return major, ai, v, nil
	case ai == 25:
		if d.pos+2 > len(d.data) {
			return 0, 0, 0, fmt.Errorf("abi: cbor: truncated 2-byte argument")
		}
		v := uint64(d.data[d.pos])<<8 | uint64(d.data[d.pos+1])
		d.pos += 2
		return major, ai, v, nil
	case ai == 26:
		if d.pos+4 > len(d.data) {
			return 0, 0, 0, fmt.Errorf("abi: cbor: truncated 4-byte argument")
		}
		v := uint64(d.data[d.pos])<<24 | uint64(d.data[d.pos+1])<<16 | uint64(d.data[d.pos+2])<<8 | uint64(d.data[d.pos+3])
		d.pos += 4
		return major, ai, v, nil
	case ai == 27:
		if d.pos+8 > len(d.data) {
			return 0, 0, 0, fmt.Errorf("abi: cbor: truncated 8-byte argument")
		}
		var v uint64
		for k := 0; k < 8; k++ {
			v = v<<8 | uint64(d.data[d.pos+k])
		}
		d.pos += 8
		return major, ai, v, nil
	default:
		return 0, 0, 0, fmt.Errorf("abi: cbor: reserved additional info %d", ai)
	}
}

func (d *cborDec) readMapHeader() (int, error) {
	major, _, arg, err := d.readHead()
	if err != nil {
		return 0, err
	}
	if major != 5 {
		return 0, fmt.Errorf("abi: cbor: expected map, got major %d", major)
	}
	return int(arg), nil
}

func (d *cborDec) readArrayHeader() (int, error) {
	major, _, arg, err := d.readHead()
	if err != nil {
		return 0, err
	}
	if major != 4 {
		return 0, fmt.Errorf("abi: cbor: expected array, got major %d", major)
	}
	return int(arg), nil
}

// readEntryKey reads the start of one entry of an order-preserving map's array
// form — a two-element array whose first element is the text-string key — and
// returns the key, leaving the value as the next item. An entry of any other
// shape is refused.
func (d *cborDec) readEntryKey() (string, error) {
	n, err := d.readArrayHeader()
	if err != nil {
		return "", err
	}
	if n != 2 {
		return "", fmt.Errorf("abi: cbor: an order-preserving map entry holds %d items, want 2", n)
	}
	return d.readTextString()
}

// duplicateKeyError is the refusal of an encoded order-preserving map that
// repeats a key, naming the key.
func duplicateKeyError(k string) error {
	return fmt.Errorf("abi: duplicate key %q", k)
}

func (d *cborDec) readTextString() (string, error) {
	major, _, arg, err := d.readHead()
	if err != nil {
		return "", err
	}
	if major != 3 {
		return "", fmt.Errorf("abi: cbor: expected text string, got major %d", major)
	}
	if d.pos+int(arg) > len(d.data) {
		return "", fmt.Errorf("abi: cbor: truncated text string")
	}
	s := string(d.data[d.pos : d.pos+int(arg)])
	d.pos += int(arg)
	return s, nil
}

func (d *cborDec) readByteString() ([]byte, error) {
	major, _, arg, err := d.readHead()
	if err != nil {
		return nil, err
	}
	if major != 2 {
		return nil, fmt.Errorf("abi: cbor: expected byte string, got major %d", major)
	}
	if d.pos+int(arg) > len(d.data) {
		return nil, fmt.Errorf("abi: cbor: truncated byte string")
	}
	out := make([]byte, arg)
	copy(out, d.data[d.pos:d.pos+int(arg)])
	d.pos += int(arg)
	return out, nil
}

func (d *cborDec) readInt() (int64, error) {
	major, _, arg, err := d.readHead()
	if err != nil {
		return 0, err
	}
	switch major {
	case 0:
		return int64(arg), nil
	case 1:
		return -1 - int64(arg), nil
	default:
		return 0, fmt.Errorf("abi: cbor: expected integer, got major %d", major)
	}
}

func (d *cborDec) readFloat() (float64, error) {
	major, ai, arg, err := d.readHead()
	if err != nil {
		return 0, err
	}
	if major != 7 {
		return 0, fmt.Errorf("abi: cbor: expected float, got major %d", major)
	}
	switch ai {
	case 25:
		return float16ToFloat64(uint16(arg)), nil
	case 26:
		return float64(math.Float32frombits(uint32(arg))), nil
	case 27:
		return math.Float64frombits(arg), nil
	default:
		return 0, fmt.Errorf("abi: cbor: expected float, got additional info %d", ai)
	}
}

func (d *cborDec) readBool() (bool, error) {
	major, ai, _, err := d.readHead()
	if err != nil {
		return false, err
	}
	if major != 7 || (ai != 20 && ai != 21) {
		return false, fmt.Errorf("abi: cbor: expected bool")
	}
	return ai == 21, nil
}

// skip consumes exactly one CBOR item (recursively for arrays and maps),
// discarding it — used for an unknown map key's value.
func (d *cborDec) skip() error {
	major, ai, arg, err := d.readHead()
	if err != nil {
		return err
	}
	switch major {
	case 0, 1, 7:
		return nil // argument already consumed by readHead
	case 2, 3:
		if d.pos+int(arg) > len(d.data) {
			return fmt.Errorf("abi: cbor: truncated string")
		}
		d.pos += int(arg)
		return nil
	case 4:
		for k := 0; k < int(arg); k++ {
			if err := d.skip(); err != nil {
				return err
			}
		}
		return nil
	case 5:
		for k := 0; k < int(arg)*2; k++ {
			if err := d.skip(); err != nil {
				return err
			}
		}
		return nil
	default:
		_ = ai
		return fmt.Errorf("abi: cbor: cannot skip major %d", major)
	}
}

// refuseUndeclaredCBORKeys walks the top-level keys of a CBOR map and reports the
// first one the declared key set does not contain. It reads only the map's own
// keys — each value is skipped whole rather than descended into — so it is the
// shape check for a payload whose identity is carried by which keys it holds.
func refuseUndeclaredCBORKeys(data []byte, declared ...string) error {
	dec := &cborDec{data: data}
	n, err := dec.readMapHeader()
	if err != nil {
		return err
	}
	for i := 0; i < n; i++ {
		key, err := dec.readTextString()
		if err != nil {
			return err
		}
		found := false
		for _, d := range declared {
			if key == d {
				found = true
				break
			}
		}
		if !found {
			return fmt.Errorf("abi: unexpected field %q", key)
		}
		if err := dec.skip(); err != nil {
			return err
		}
	}
	return nil
}
